     "જમણી બાજુનું 2 Term table ಕಾಲમ નિયમો ધરાવે છે. **પ્રતિ લીટી એક નિયમ**, જૂની શરત અને નવી શરત `->` , `=>` , `→` અથવા ટેબ દ્વારા અલગ કરેલ છે — ચારેય કામ કરે છે. `#` થી શરૂ થતી લીટીઓ ટિપ્પણીઓ છે અને રિપ્લેસમેન્ટમાં કોઈ ભાગ લેતી નથી.",
