     "સ્ટાઇલિંગ માત્ર દેખાવ બદલે છે, ડાયલોગ ક્યારેય નહીં. મર્જ દરમિયાન મૂળ અને અનુવાદના ટેક્સ્ટમાં એક અક્ષરનો પણ ફેરફાર થતો નથી; જ્યાં સુધી તમે પ્રિવ્યુ નીચેના એડજસ્ટમેન્ટ એરિયામાં તેને ઇરાદાપૂર્વક ન બદલો, ત્યાં સુધી ટાઇમલાઇન તમે પસંદ કરેલી ફાઇલમાંથી આવે છે.",
     "જ્યારે તમે SRT અથવા \"સ્ટાઇલ વિનાનું VTT\" એક્સપોર્ટ કરો છો, ત્યારે ફાઇલમાં કોઈ સ્ટાઇલ માહિતી લખવામાં આવતી નથી — પેજ તમને જણાવે છે કે VTT માં કોઈ STYLE બ્લોક નથી અને પ્લેયર તેના ડિફોલ્ટ દેખાવનો ઉપયોગ કરશે. જો તમને સ્ટાઇલ જોઈતી હોય, તો દ્વિભાષી VTT સ્ટાઇલિંગ અથવા ASS પસંદ કરો."
